import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:openvalut/openvalut_cloud/openvalut_crypto.dart';

Uint8List _hex(String s) => Uint8List.fromList(
  List.generate(
    s.length ~/ 2,
    (i) => int.parse(s.substring(i * 2, i * 2 + 2), radix: 16),
  ),
);

String _toHex(List<int> bytes) =>
    [for (final b in bytes) b.toRadixString(16).padLeft(2, '0')].join();

// Known-answer vector generated by the Go server (server/internal/crypto):
// Argon2id("test-password", salt "0123456789abcdef") -> key below, then
// AES-256-GCM over the payload with nonce 00..0b.
const _goKey =
    'd774d399883c545c11b8dc7253c37ce196dca2c3234964b8dc91f39ef894871c';
const _goNonce = '000102030405060708090a0b';
const _goCt =
    '94608bbb76c5c2d8afcf9a8799d427f593096bd526e79e24bec47859ce75fe3c'
    '98b5862825f30ba1b3b3c510c55d64a7e14d31e47fb08a1a50af4632be665acf'
    '8f36bace97b4851065a6467e7cd9';
const _payload =
    '{"label":"GitHub","username":"octocat","password":"gh-secret"}';

void main() {
  test('Argon2id derives the same key as the Go server', () async {
    try {
      final key = await openvalutCrypto.deriveKey(
        'test-password',
        Uint8List.fromList(utf8.encode('0123456789abcdef')),
      );
      expect(_toHex(key), _goKey);
    } catch (e) {
      // The argon2 FFI library may not be loadable inside `flutter test`.
      markTestSkipped('argon2 FFI unavailable: $e');
    }
  });

  test('Dart AES-GCM decrypts the Go server ciphertext', () {
    final plain = openvalutCrypto.decrypt(
      _hex(_goKey),
      _hex(_goNonce),
      _hex(_goCt),
    );
    expect(utf8.decode(plain), _payload);
  });

  test('encrypt/decrypt round-trips and authenticates', () {
    final key = _hex(_goKey);
    final (nonce, ct) = openvalutCrypto.encrypt(
      key,
      Uint8List.fromList(utf8.encode(_payload)),
    );
    expect(nonce.length, openvalutCrypto.nonceLength);
    expect(utf8.decode(openvalutCrypto.decrypt(key, nonce, ct)), _payload);

    // Tampering must fail authentication.
    final bad = Uint8List.fromList(ct);
    bad[0] ^= 0xff;
    expect(
      () => openvalutCrypto.decrypt(key, nonce, bad),
      throwsA(anything),
    );
  });
}
